   321          int free_ret, empty;
   322
   323          p = *data;
   324          while (*p == ' ') p++;
   325
   326          if (*p == '}') {
   327                  /* empty */
   328                  *data = p+1;
   329                  return TRUE;
   330          }
   590                  } else if (format[1] != '\0') {
   591                          /* %format */
   592                          format++;
   593                          if (IS_OLD_FORMAT(*format, last_fg, last_bg)) {
   594                                  /* active color set again */
   595                          } else if (IS_FGCOLOR_FORMAT(*format) &&
