   599                                  /* two fg colors in a row. bg colors are
   600                                     so rare that we don't bother checking
   601                                     them */
   602                          } else {
   603                                  /* some format, add it */
   604                                  g_string_append_c(str, '%');
   605                                  g_string_append_c(str, *format);
   606
   607                                  if (IS_FGCOLOR_FORMAT(*format))
   608                                          last_fg = *format;
   609                                  else if (*format == 'Z' || *format == 'X')
   610                                          last_fg = '\0';
   611                                  if (IS_BGCOLOR_FORMAT(*format))
   612                                          last_bg = *format;
   613                                  else if (*format == 'z' || *format == 'x')
   614                                          last_bg = '\0';
   615                          }
   616                          format++;
   617                  } else {
   618                          /* % at end of string */
   619                          format++;
   620                          g_string_append_c(str, '%');
   621                          g_string_append_c(str, '%');
   622                  }
   623          }
   624
   625          ret = str->str;
