   646  static MODULE_THEME_REC *theme_module_create(THEME_REC *theme, const char *module)
   647  {
   648          MODULE_THEME_REC *rec;
   649          FORMAT_REC *formats;
   650
   651          rec = g_hash_table_lookup(theme->modules, module);
   652          if (rec != NULL) return rec;
   653
