   656
   657          rec = g_new0(MODULE_THEME_REC, 1);
   658          rec->name = g_strdup(module);
   659
   660          for (rec->count = 0; formats[rec->count].def != NULL; rec->count++) ;
   661          rec->formats = g_new0(char *, rec->count);
   662          rec->expanded_formats = g_new0(char *, rec->count);
   663
   664          g_hash_table_insert(theme->modules, rec->name, rec);
   665          return rec;
   666  }
