   668  static void theme_read_replaces(CONFIG_REC *config, THEME_REC *theme)
   669  {
   670          GSList *tmp;
   671          CONFIG_NODE *node;
   672          const char *p;
   673          int index;
   674
   675          /* reset replace keys */
   676          for (index = 0; index < 256; index++)
   677                  theme->replace_keys[index] = -1;
   678          index = 0;
   679
   680          node = config_node_traverse(config, "replaces", FALSE);
   681          if (node == NULL || node->type !=  NODE_TYPE_BLOCK) return;
   682
   683          for (tmp = node->value; tmp != NULL; tmp = tmp->next) {
   684                  node = tmp->data;
   685
   686                  if (node->key != NULL && node->value != NULL) {
   687                          for (p = node->key; *p != '\0'; p++)
   688                                  theme->replace_keys[(int) (unsigned char) *p] = index;
   689
   690                          theme->replace_values =
   691                                  g_slist_append(theme->replace_values,
   692                                                 g_strdup(node->value));
   693                          index++;
   694                  }
   695          }
   696  }
