   698  static void theme_read_abstracts(CONFIG_REC *config, THEME_REC *theme)
   699  {
   700          GSList *tmp;
   701          CONFIG_NODE *node;
   702          gpointer oldkey, oldvalue;
   703
   704          node = config_node_traverse(config, "abstracts", FALSE);
   705          if (node == NULL || node->type !=  NODE_TYPE_BLOCK) return;
   706
   707          for (tmp = node->value; tmp != NULL; tmp = tmp->next) {
   708                  node = tmp->data;
   709
   710                  if (node->key == NULL || node->value == NULL)
   711                          continue;
   712
   713                  if (g_hash_table_lookup_extended(theme->abstracts, node->key,
   714                                                   &oldkey, &oldvalue)) {
   715                          /* new values override old ones */
   716                          g_hash_table_remove(theme->abstracts, oldkey);
   717                          g_free(oldkey);
   718                          g_free(oldvalue);
   719                  }
   720
   721                  g_hash_table_insert(theme->abstracts, g_strdup(node->key),
   722                                      g_strdup(node->value));
   723          }
   724  }
