   760  static void theme_init_module(THEME_REC *theme, const char *module,
   761                                CONFIG_REC *config)
   762  {
   763          MODULE_THEME_REC *rec;
   764          FORMAT_REC *formats;
   765          int n;
   766
   767          formats = g_hash_table_lookup(default_formats, module);
   768          g_return_if_fail(formats != NULL);
   769
   770          rec = theme_module_create(theme, module);
   771
   772          if (config != NULL)
   773                  theme_read_formats(theme, module, config, rec);
   774
   775          /* expand the remaining formats */
   776          for (n = 0; n < rec->count; n++) {
   777                  if (rec->expanded_formats[n] == NULL) {
   778                          rec->expanded_formats[n] =
   779                                  theme_format_expand(theme, formats[n].def);
   780                  }
   781          }
   782  }
